import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Register.css';

function Register() {
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e) => 
    {
    e.preventDefault();

    if (!username || !email || !password || !confirmPassword) 
    {
      alert('Completează toate câmpurile!');
      return;
    }

    if (password !== confirmPassword)
   {
      alert('Parolele nu se potrivesc!');
      return;
    }

    console.log('Username:', username);
    console.log('Email:', email);
    console.log('Password:', password);

    setSubmitted(true);
  };

  return (
    <div className="register-container">
      <h1>Înregistrare</h1>
      
      <form onSubmit={handleSubmit}>
        <input type="text"   placeholder="Username"  value={username}  onChange={(e) => setUsername(e.target.value)} />
        <input type="email"  placeholder="Email"     value={email}     onChange={(e) => setEmail(e.target.value)}/>
        <input type="password"  placeholder="Parolă"  value={password} onChange={(e) => setPassword(e.target.value)}/>
        <input type="password"  placeholder="Confirmă parola"  value={confirmPassword}  onChange={(e) => setConfirmPassword(e.target.value)} />
        
        <button type="submit">Înregistrează-te</button>

        <p style={{ textAlign: 'center', marginTop: '15px' }}> Ai deja un cont? <Link to="/login">Autentifică-te</Link></p>
      </form>

      {submitted && (
        <p style={{ color: 'green' }}> Utilizator înregistrat cu succes! </p>
      )}
    </div>
  );
}

export default Register;
